        else:
            self.rear.next = self.stack1

    def dequeue(self):
        if self.front is None:
            return None
        item = self.front.pop()
        self.front = self.front.next
        if self.front is None:
            self.rear = None
        return item

    def is_empty(self):
        return self.front is None

    def __repr__(self):
        if self.is_empty():
            return "Empty Queue"
        else:
            return f"Queue with {len(self.items)} items"
